INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d83f15e9-ac51-5ab0-b1f5-bf1e345078c9', 'UK International Corporate Governance Principles', 'International Corporate Governance Principles, 1999', 'The overriding objective of the corporation should be to optimise over time the returns to its shareholders. Where other considerations affect this objective, they should be clearly stated and disclosed. To achieve this objective, the corporation should endeavour to ensure the long-term viability of its business, and to manage effectively its relationships with stakeholders.', 'The overriding objective of the corporation should be to optimise over time the returns to its shareholders. Where other considerations affect this objective, they should be clearly stated and disclosed. To achieve this objective, the corporation should endeavour to ensure the long-term viability of its business, and to manage effectively its relationships with stakeholders.', 'The overriding objective of the corporation should be to optimise over time the returns to its shareholders. Where other considerations affect this objective, they should be clearly stated and disclosed. To achieve this objective, the corporation should endeavour to ensure the long-term viability of its business, and to manage effectively its relationships with stakeholders.', 'UK', 'governance', 'in_force', '1999-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_50', ARRAY['guidance_frameworks', 'uk', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5034195f-788b-50b1-807b-4c2b23aea456', 'UK Internal Control. Guidance for Directors on the Combined', 'Internal Control. Guidance for Directors on the Combined Code, 1999', 'This guidance is intended to: (1) reflect sound business practice whereby internal control is embedded in the business processes by which a company pursues its objectives; (2) remain relevant over time in the continually evolving business environment; and (3) enable each company to apply it in a manner which takes account of its particular circumstances. The guidance requires directors to exercise judgement in reviewing how the company has implemented the requirements of the Code relating to internal control and reporting to shareholders thereon. The guidance is based on the adoption by a company’s board of a risk-based approach to establishing a sound system of internal control and reviewing its effectiveness. This should be incorporated by the company within its normal management and governance processes. It should not be treated as a separate exercise undertaken to meet regulatory requirements.', 'This guidance is intended to: (1) reflect sound business practice whereby internal control is embedded in the business processes by which a company pursues its objectives; (2) remain relevant over time in the continually evolving business environment; and (3) enable each company to apply it in a manner which takes account of its particular circumstances. The guidance requires directors to exercise judgement in reviewing how the company has implemented the requirements of the Code relating to internal control and reporting to shareholders thereon. The guidance is based on the adoption by a company’s board of a risk-based approach to establishing a sound system of internal control and reviewing its effectiveness. This should be incorporated by the company within its normal management and governance processes. It should not be treated as a separate exercise undertaken to meet regulatory requirements.', 'This guidance is intended to: (1) reflect sound business practice whereby internal control is embedded in the business processes by which a company pursues its objectives; (2) remain relevant over time in the continually evolving business environment; and (3) enable each company to apply it in a manner which takes account of its particular circumstances. The guidance requires directors to exercise judgement in reviewing how the company has implemented the requirements of the Code relating to internal control and reporting to shareholders thereon. The guidance is based on the adoption by a company’s board of a risk-based approach to establishing a sound system of internal control and reviewing its effectiveness. This should be incorporated by the company within its normal management and governance processes. It should not be treated as a separate exercise undertaken to meet regulatory requirements.', 'UK', 'climate', 'in_force', '1999-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_51', ARRAY['guidance_frameworks', 'uk', 'mandatory', 'sdg16', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('98c2ca1f-6359-504c-afb6-eeb91ad65202', 'UK KPMG Review. Internal Control: A Practical Guide', 'The KPMG Review. Internal Control: A Practical Guide, 1999', 'Despite speculation in the financial press that the final guidance on internal control would be essentially similar to April’s consultative document, the final guidance was significantly tightened by the removal of the option for a single annual review. This should act to discourage bureaucratic procedures that provide neither the depth nor quality of  information provided by the now required regular review process. KPMG is particularly pleased to see that the final guidance reflects many of the recommendations made in their response to the consultative document.', 'Despite speculation in the financial press that the final guidance on internal control would be essentially similar to April’s consultative document, the final guidance was significantly tightened by the removal of the option for a single annual review. This should act to discourage bureaucratic procedures that provide neither the depth nor quality of  information provided by the now required regular review process. KPMG is particularly pleased to see that the final guidance reflects many of the recommendations made in their response to the consultative document.', 'Despite speculation in the financial press that the final guidance on internal control would be essentially similar to April’s consultative document, the final guidance was significantly tightened by the removal of the option for a single annual review. This should act to discourage bureaucratic procedures that provide neither the depth nor quality of  information provided by the now required regular review process. KPMG is particularly pleased to see that the final guidance reflects many of the recommendations made in their response to the consultative document.', 'UK', 'governance', 'in_force', '1999-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_64', ARRAY['disclosure', 'mandatory', 'uk', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6ddcbe7a-798c-59f2-8a09-088a5760e2aa', 'UK Competition Act', 'Competition Act, 1998', 'The Competition Act 1998 is the current major source of competition law in the United Kingdom, along with the Enterprise Act 2002. The act provides an updated framework for identifying and dealing with restrictive business practices and abuse of a dominant market position.', 'The Competition Act 1998 is the current major source of competition law in the United Kingdom, along with the Enterprise Act 2002. The act provides an updated framework for identifying and dealing with restrictive business practices and abuse of a dominant market position.', 'The Competition Act 1998 is the current major source of competition law in the United Kingdom, along with the Enterprise Act 2002. The act provides an updated framework for identifying and dealing with restrictive business practices and abuse of a dominant market position.', 'UK', 'governance', 'in_force', '1998-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_104', ARRAY['mandatory', 'other sustainability policy', 'uk', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c607c619-67cd-5198-915a-0fe7208f2dda', 'UK Hampel Report: Committee on Corporate Governance Final Report', 'Hampel Report: Committee on Corporate Governance Final Report, 1998', 'The Hampel Report was designed to be a revision of the corporate governance system in the UK. The remit of the committee was to review the Code laid down by the Cadbury Report. It asked whether the code''s original purpose was being achieved.', 'The Hampel Report was designed to be a revision of the corporate governance system in the UK. The remit of the committee was to review the Code laid down by the Cadbury Report. It asked whether the code''s original purpose was being achieved.', 'The Hampel Report was designed to be a revision of the corporate governance system in the UK. The remit of the committee was to review the Code laid down by the Cadbury Report. It asked whether the code''s original purpose was being achieved.', 'UK', 'climate', 'in_force', '1998-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_49', ARRAY['uk', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2c6fe9e2-b709-58ba-b60e-4a133c2f606b', 'UN Adoption of the Paris Agreement : Draft Decision', 'Adoption of the Paris Agreement : Draft Decision -/cp.21 : Proposal / by the President', 'This document is concerned with the Adoption of the Paris Agreement under the United Nations Framework Convention on Climate Change.', 'This document is concerned with the Adoption of the Paris Agreement under the United Nations Framework Convention on Climate Change.', 'This document is concerned with the Adoption of the Paris Agreement under the United Nations Framework Convention on Climate Change.', 'UN', 'climate', 'in_force', '2015-01-01'::date, 'United Nations General Assembly (UNGA)', 'https://www.carrotsandsticks.org/policies/328_4', ARRAY['sdg13', 'mandatory', 'mandatory_regulations', 'disclosure', 'un']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('284c207d-57ab-5f17-b7ad-4730d1d15c43', 'UN Good Practices in Corporate Governance Disclosure', 'Guidance on Good Practices in Corporate Governance Disclosure', 'This guidance is a technical aid for regulators and companies, particularly in developing countries and transition economies. The purpose of the guidance is to help those responsible for preparing company reports to produce disclosures on corporate governance that address the major concerns of investors and other stakeholders.', 'This guidance is a technical aid for regulators and companies, particularly in developing countries and transition economies. The purpose of the guidance is to help those responsible for preparing company reports to produce disclosures on corporate governance that address the major concerns of investors and other stakeholders.', 'This guidance is a technical aid for regulators and companies, particularly in developing countries and transition economies. The purpose of the guidance is to help those responsible for preparing company reports to produce disclosures on corporate governance that address the major concerns of investors and other stakeholders.', 'UN', 'climate', 'in_force', '2006-01-01'::date, 'United Nations General Assembly (UNGA)', 'https://www.carrotsandsticks.org/policies/328_6', ARRAY['regulations', 'sdg16', 'disclosure', 'voluntary', 'un']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5176ba5a-0fe3-54bb-8b6f-aed6a50c6922', 'UN Guiding Principles on Business and Human Rights. Implementing', 'Guiding Principles on Business and Human Rights. Implementing the United Nations “Protect, Respect and Remedy” Framework', 'The UN Guiding Principles on Business and Human Rights are a set of guidelines for States and companies to prevent, address and remedy human rights abuses committed in business operations.', 'The UN Guiding Principles on Business and Human Rights are a set of guidelines for States and companies to prevent, address and remedy human rights abuses committed in business operations.', 'The UN Guiding Principles on Business and Human Rights are a set of guidelines for States and companies to prevent, address and remedy human rights abuses committed in business operations.', 'UN', 'governance', 'in_force', '2011-01-01'::date, 'United Nations Human Rights Council (UNHR)', 'https://www.carrotsandsticks.org/policies/330_1', ARRAY['voluntary_frameworks', 'other sustainability policy', 'sdg16', 'voluntary', 'un']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('93343788-784f-52e9-9fe3-31cf78db9a19', 'California Climate Accountability Package', 'California Climate Accountability Package', 'The Climate Corporate Data Accountability Act (SB-253) is a California law designed to enhance transparency and accountability in corporate greenhouse gas (GHG) emissions reporting. Key provisions include:

Reporting Requirements: Starting in 2026, companies with annual revenues exceeding $1 billion and operating in California must disclose their Scope 1 (direct emissions) and Scope 2 (indirect emissions) GHG data. By 2027, they must also report Scope 3 emissions (indirect upstream and downstream emissions).
Assurance Engagement: Companies are required to obtain independent third-party verification of reported emissions, with levels of assurance increasing over time.
Digital Platform: A public platform will be established to display emissions data, accessible to consumers, investors, and stakeholders.
Penalties: Administrative penalties of up to $500,000 may be imposed for noncompliance, but leniency is provided for good-faith Scope 3 disclosures between 2027 and 2030.
Stakeholder Collaboration: Regulations will be developed in consultation with stakeholders, including climate experts, consumer groups, and businesses.
The act aims to align corporate emissions reporting with California''s climate goals and global standards, fostering a transparent and net-zero economy.', 'The Climate Corporate Data Accountability Act (SB-253) is a California law designed to enhance transparency and accountability in corporate greenhouse gas (GHG) emissions reporting. Key provisions include:

Reporting Requirements: Starting in 2026, companies with annual revenues exceeding $1 billion and operating in California must disclose their Scope 1 (direct emissions) and Scope 2 (indirect emissions) GHG data. By 2027, they must also report Scope 3 emissions (indirect upstream and downstream emissions).
Assurance Engagement: Companies are required to obtain independent third-party verification of reported emissions, with levels of assurance increasing over time.
Digital Platform: A public platform will be established to display emissions data, accessible to consumers, investors, and stakeholders.
Penalties: Administrative penalties of up to $500,000 may be imposed for noncompliance, but leniency is provided for good-faith Scope 3 disclosures between 2027 and 2030.
Stakeholder Collaboration: Regulations will be developed in consultation with stakeholders, including climate experts, consumer groups, and businesses.
The act aims to align corporate emissions reporting with California''s climate goals and global standards, fostering a transparent and net-zero economy.', 'The Climate Corporate Data Accountability Act (SB-253) is a California law designed to enhance transparency and accountability in corporate greenhouse gas (GHG) emissions reporting. Key provisions include:

Reporting Requirements: Starting in 2026, companies with annual revenues exceeding $1 billion and operating in California must disclose their Scope 1 (direct emissions) and Scope 2 (indirect emissions) GHG data. By 2027, they must also report Scope 3 emissions (indirect upstream and downstream emissions).
Assurance Engagement: Companies are required to obtain independent third-party verification of reported emissions, with levels of assurance increasing over time.
Digital Platform: A public platform will be established to display emissions data, accessible to consumers, investors, and stakeholders.
Penalties: Administrative penalties of up to $500,000 may be imposed for noncompliance, but leniency is provided for good-faith Scope 3 disclosures between 2027 and 2030.
Stakeholder Collaboration: Regulations will be developed in consultation with stakeholders, including climate experts, consumer groups, and businesses.
The act aims to align corporate emissions reporting with California''s climate goals and global standards, fostering a transparent and net-zero economy.', 'USA', 'climate', 'in_force', '2024-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_200', ARRAY['sdg13', 'regulations', 'sdg7', 'sdg17', 'mandatory', 'usa', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('be8ebaec-2564-545e-a12a-798a0c1a6fdd', 'USA Colorado Battery Stewardship Programs', 'Colorado Battery Stewardship Programs', 'Colorado’s SB 25-163 establishes a statewide battery stewardship program that requires producers of batteries and battery-containing products to finance and manage end-of-life collection and recycling. Starting July 1, 2026, producers must join a stewardship organization and submit a plan to the Department of Public Health and Environment. The plan must ensure free, convenient, and accessible recycling options for consumers. Covered batteries include both rechargeable and single-use batteries. Producers must also meet performance goals, educate consumers, and provide annual reports. The law encourages a circular economy by ensuring responsible battery disposal and reducing environmental harm from hazardous waste. Enforcement includes penalties for noncompliance. The act aligns with Colorado’s broader sustainability goals, aiming to increase recycling rates and reduce toxic waste in landfills. It reflects a growing trend among states to shift waste management responsibility to manufacturers through extended producer responsibility (EPR) frameworks.', 'Colorado’s SB 25-163 establishes a statewide battery stewardship program that requires producers of batteries and battery-containing products to finance and manage end-of-life collection and recycling. Starting July 1, 2026, producers must join a stewardship organization and submit a plan to the Department of Public Health and Environment. The plan must ensure free, convenient, and accessible recycling options for consumers. Covered batteries include both rechargeable and single-use batteries. Producers must also meet performance goals, educate consumers, and provide annual reports. The law encourages a circular economy by ensuring responsible battery disposal and reducing environmental harm from hazardous waste. Enforcement includes penalties for noncompliance. The act aligns with Colorado’s broader sustainability goals, aiming to increase recycling rates and reduce toxic waste in landfills. It reflects a growing trend among states to shift waste management responsibility to manufacturers through extended producer responsibility (EPR) frameworks.', 'Colorado’s SB 25-163 establishes a statewide battery stewardship program that requires producers of batteries and battery-containing products to finance and manage end-of-life collection and recycling. Starting July 1, 2026, producers must join a stewardship organization and submit a plan to the Department of Public Health and Environment. The plan must ensure free, convenient, and accessible recycling options for consumers. Covered batteries include both rechargeable and single-use batteries. Producers must also meet performance goals, educate consumers, and provide annual reports. The law encourages a circular economy by ensuring responsible battery disposal and reducing environmental harm from hazardous waste. Enforcement includes penalties for noncompliance. The act aligns with Colorado’s broader sustainability goals, aiming to increase recycling rates and reduce toxic waste in landfills. It reflects a growing trend among states to shift waste management responsibility to manufacturers through extended producer responsibility (EPR) frameworks.', 'USA', 'climate', 'in_force', '2024-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_86', ARRAY['regulations', 'mandatory', 'usa', 'sdg12', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dca84b65-a6fb-578e-b158-9486e5b11ea2', 'USA Colorado Biometric Data Protection Act', 'Colorado Biometric Data Protection Act', 'HB 24-1130 strengthens biometric data protections in Colorado by imposing strict consent and data-handling requirements. Biometric identifiers—like fingerprints, retina scans, or facial geometry—may not be collected, stored, or disclosed without informed, written consent. Entities must detail the purpose, retention period, and security measures for the data, and are prohibited from profiting from biometric information. Consumers have the right to access and delete their data. The law also requires entities to implement reasonable security safeguards and data minimization practices. Public agencies are not exempt, and violations can be enforced by the Attorney General under the Colorado Consumer Protection Act. The law aims to address growing concerns about surveillance, data breaches, and misuse of sensitive biometric data. It places Colorado among the most privacy-forward states, mirroring elements of Illinois'' Biometric Information Privacy Act (BIPA), and reflects national momentum toward stronger consumer data protections', 'HB 24-1130 strengthens biometric data protections in Colorado by imposing strict consent and data-handling requirements. Biometric identifiers—like fingerprints, retina scans, or facial geometry—may not be collected, stored, or disclosed without informed, written consent. Entities must detail the purpose, retention period, and security measures for the data, and are prohibited from profiting from biometric information. Consumers have the right to access and delete their data. The law also requires entities to implement reasonable security safeguards and data minimization practices. Public agencies are not exempt, and violations can be enforced by the Attorney General under the Colorado Consumer Protection Act. The law aims to address growing concerns about surveillance, data breaches, and misuse of sensitive biometric data. It places Colorado among the most privacy-forward states, mirroring elements of Illinois'' Biometric Information Privacy Act (BIPA), and reflects national momentum toward stronger consumer data protections', 'HB 24-1130 strengthens biometric data protections in Colorado by imposing strict consent and data-handling requirements. Biometric identifiers—like fingerprints, retina scans, or facial geometry—may not be collected, stored, or disclosed without informed, written consent. Entities must detail the purpose, retention period, and security measures for the data, and are prohibited from profiting from biometric information. Consumers have the right to access and delete their data. The law also requires entities to implement reasonable security safeguards and data minimization practices. Public agencies are not exempt, and violations can be enforced by the Attorney General under the Colorado Consumer Protection Act. The law aims to address growing concerns about surveillance, data breaches, and misuse of sensitive biometric data. It places Colorado among the most privacy-forward states, mirroring elements of Illinois'' Biometric Information Privacy Act (BIPA), and reflects national momentum toward stronger consumer data protections', 'USA', 'governance', 'in_force', '2024-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_88', ARRAY['usa', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0333823c-e06c-5927-8ac5-734272b2e54a', 'USA Maryland Online Data Privacy Act of', 'Maryland Online Data Privacy Act of 2024', 'The Maryland Online Data Privacy Act (HB 567) provides residents with sweeping rights over their personal data, including access, deletion, correction, and opt-out of targeted advertising or data sales. Effective from 2025, the law applies to businesses that handle the personal data of 35,000+ Marylanders or derive over 20% of revenue from selling data. Covered entities must conduct privacy impact assessments, limit data collection to necessary purposes, and obtain clear consent for sensitive data like health, biometric, or children''s information. Data minimization, purpose limitation, and security obligations are central to compliance. The act prohibits “dark patterns” that manipulate consent and empowers the Attorney General to enforce violations with civil penalties. Maryland’s law aligns with national data privacy trends and incorporates consumer protection principles seen in California’s CCPA/CPRA and Virginia’s CDPA, advancing individual rights and holding businesses accountable in the digital economy.', 'The Maryland Online Data Privacy Act (HB 567) provides residents with sweeping rights over their personal data, including access, deletion, correction, and opt-out of targeted advertising or data sales. Effective from 2025, the law applies to businesses that handle the personal data of 35,000+ Marylanders or derive over 20% of revenue from selling data. Covered entities must conduct privacy impact assessments, limit data collection to necessary purposes, and obtain clear consent for sensitive data like health, biometric, or children''s information. Data minimization, purpose limitation, and security obligations are central to compliance. The act prohibits “dark patterns” that manipulate consent and empowers the Attorney General to enforce violations with civil penalties. Maryland’s law aligns with national data privacy trends and incorporates consumer protection principles seen in California’s CCPA/CPRA and Virginia’s CDPA, advancing individual rights and holding businesses accountable in the digital economy.', 'The Maryland Online Data Privacy Act (HB 567) provides residents with sweeping rights over their personal data, including access, deletion, correction, and opt-out of targeted advertising or data sales. Effective from 2025, the law applies to businesses that handle the personal data of 35,000+ Marylanders or derive over 20% of revenue from selling data. Covered entities must conduct privacy impact assessments, limit data collection to necessary purposes, and obtain clear consent for sensitive data like health, biometric, or children''s information. Data minimization, purpose limitation, and security obligations are central to compliance. The act prohibits “dark patterns” that manipulate consent and empowers the Attorney General to enforce violations with civil penalties. Maryland’s law aligns with national data privacy trends and incorporates consumer protection principles seen in California’s CCPA/CPRA and Virginia’s CDPA, advancing individual rights and holding businesses accountable in the digital economy.', 'USA', 'nature', 'in_force', '2024-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_89', ARRAY['regulations', 'mandatory', 'usa', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b62bb54a-c1c1-557a-aa8f-316e66802455', 'USA Minnesota Consumer Data Policy', 'Minnesota Consumer Data Policy', 'Minnesota’s HF 4757 grants state residents extensive control over their personal data and mandates transparent data practices for businesses. Effective July 31, 2025, it applies to companies processing data from 100,000+ consumers annually or earning 25%+ revenue from selling data. Consumers can access, correct, delete, and port their data and opt out of profiling, targeted ads, and data sales. Businesses must conduct data protection assessments for high-risk processing and must not process sensitive data without explicit consent. Unique to Minnesota’s law is a requirement for “data protection by design and by default,” emphasizing proactive privacy integration. The Attorney General enforces compliance, with civil penalties for violations. HF 4757 builds upon laws from Virginia, Colorado, and California, blending business accountability with user empowerment. It underscores Minnesota’s commitment to digital rights and creates a consistent framework for privacy while allowing businesses time to adapt.', 'Minnesota’s HF 4757 grants state residents extensive control over their personal data and mandates transparent data practices for businesses. Effective July 31, 2025, it applies to companies processing data from 100,000+ consumers annually or earning 25%+ revenue from selling data. Consumers can access, correct, delete, and port their data and opt out of profiling, targeted ads, and data sales. Businesses must conduct data protection assessments for high-risk processing and must not process sensitive data without explicit consent. Unique to Minnesota’s law is a requirement for “data protection by design and by default,” emphasizing proactive privacy integration. The Attorney General enforces compliance, with civil penalties for violations. HF 4757 builds upon laws from Virginia, Colorado, and California, blending business accountability with user empowerment. It underscores Minnesota’s commitment to digital rights and creates a consistent framework for privacy while allowing businesses time to adapt.', 'Minnesota’s HF 4757 grants state residents extensive control over their personal data and mandates transparent data practices for businesses. Effective July 31, 2025, it applies to companies processing data from 100,000+ consumers annually or earning 25%+ revenue from selling data. Consumers can access, correct, delete, and port their data and opt out of profiling, targeted ads, and data sales. Businesses must conduct data protection assessments for high-risk processing and must not process sensitive data without explicit consent. Unique to Minnesota’s law is a requirement for “data protection by design and by default,” emphasizing proactive privacy integration. The Attorney General enforces compliance, with civil penalties for violations. HF 4757 builds upon laws from Virginia, Colorado, and California, blending business accountability with user empowerment. It underscores Minnesota’s commitment to digital rights and creates a consistent framework for privacy while allowing businesses time to adapt.', 'USA', 'climate', 'in_force', '2024-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_90', ARRAY['usa', 'sdg16', 'mandatory', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7980f809-c64e-5ba7-895d-47751fe23f57', 'SEC Climate-Related Disclosure Rule (Enhancement and Standardization', 'SEC Climate-Related Disclosure Rule (Enhancement and Standardization of Climate-Related Disclosures)', 'This SEC rule amends existing disclosure requirements under the Securities Act of 1933 and the Securities Exchange Act of 1934. It mandates public companies to disclose specific climate-related risks that could materially affect their business, operations, or financial condition. The disclosures include the physical and transition risks from climate change, governance structures addressing these risks, and greenhouse gas (GHG) emissions metrics. The rule also requires companies to detail any climate-related targets, goals, and strategies, alongside their financial impacts. GHG emissions data, specifically Scope 1 and 2, must be audited for larger companies. Additionally, registrants must provide scenario analyses, transition plans, and internal carbon pricing if material. The rule aims to enhance comparability, reliability, and transparency for investors, allowing better-informed investment and voting decisions.', 'This SEC rule amends existing disclosure requirements under the Securities Act of 1933 and the Securities Exchange Act of 1934. It mandates public companies to disclose specific climate-related risks that could materially affect their business, operations, or financial condition. The disclosures include the physical and transition risks from climate change, governance structures addressing these risks, and greenhouse gas (GHG) emissions metrics. The rule also requires companies to detail any climate-related targets, goals, and strategies, alongside their financial impacts. GHG emissions data, specifically Scope 1 and 2, must be audited for larger companies. Additionally, registrants must provide scenario analyses, transition plans, and internal carbon pricing if material. The rule aims to enhance comparability, reliability, and transparency for investors, allowing better-informed investment and voting decisions.', 'This SEC rule amends existing disclosure requirements under the Securities Act of 1933 and the Securities Exchange Act of 1934. It mandates public companies to disclose specific climate-related risks that could materially affect their business, operations, or financial condition. The disclosures include the physical and transition risks from climate change, governance structures addressing these risks, and greenhouse gas (GHG) emissions metrics. The rule also requires companies to detail any climate-related targets, goals, and strategies, alongside their financial impacts. GHG emissions data, specifically Scope 1 and 2, must be audited for larger companies. Additionally, registrants must provide scenario analyses, transition plans, and internal carbon pricing if material. The rule aims to enhance comparability, reliability, and transparency for investors, allowing better-informed investment and voting decisions.', 'USA', 'nature', 'in_force', '2024-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_91', ARRAY['sdg14', 'regulations', 'mandatory', 'usa', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7980f809-c64e-5ba7-895d-47751fe23f57', 'USA Tennessee-2023-HB1181-Chaptered', 'Tennessee-2023-HB1181-Chaptered', 'The Tennessee Information Protection Act (HB 1181) establishes data privacy rights for Tennessee residents and responsibilities for businesses that control or process personal data. The law grants consumers rights to access, delete, correct, and opt out of personal data processing for advertising, sale, or profiling. It defines "personal data" broadly but excludes public and de-identified information. Sensitive data (e.g., biometric, health, geolocation) requires explicit consent. Controllers must implement reasonable data security practices, perform data protection assessments for high-risk activities, and ensure contracts with processors include privacy obligations. The law includes exemptions for certain entities like nonprofits, HIPAA-covered entities, and small businesses. Enforcement is by the Attorney General, with a 60-day cure period before civil penalties are imposed. Effective July 1, 2025, the act aligns with other state-level privacy laws and aims to provide Tennesseans more control over how their information is collected and used.', 'The Tennessee Information Protection Act (HB 1181) establishes data privacy rights for Tennessee residents and responsibilities for businesses that control or process personal data. The law grants consumers rights to access, delete, correct, and opt out of personal data processing for advertising, sale, or profiling. It defines "personal data" broadly but excludes public and de-identified information. Sensitive data (e.g., biometric, health, geolocation) requires explicit consent. Controllers must implement reasonable data security practices, perform data protection assessments for high-risk activities, and ensure contracts with processors include privacy obligations. The law includes exemptions for certain entities like nonprofits, HIPAA-covered entities, and small businesses. Enforcement is by the Attorney General, with a 60-day cure period before civil penalties are imposed. Effective July 1, 2025, the act aligns with other state-level privacy laws and aims to provide Tennesseans more control over how their information is collected and used.', 'The Tennessee Information Protection Act (HB 1181) establishes data privacy rights for Tennessee residents and responsibilities for businesses that control or process personal data. The law grants consumers rights to access, delete, correct, and opt out of personal data processing for advertising, sale, or profiling. It defines "personal data" broadly but excludes public and de-identified information. Sensitive data (e.g., biometric, health, geolocation) requires explicit consent. Controllers must implement reasonable data security practices, perform data protection assessments for high-risk activities, and ensure contracts with processors include privacy obligations. The law includes exemptions for certain entities like nonprofits, HIPAA-covered entities, and small businesses. Enforcement is by the Attorney General, with a 60-day cure period before civil penalties are imposed. Effective July 1, 2025, the act aligns with other state-level privacy laws and aims to provide Tennesseans more control over how their information is collected and used.', 'USA', 'nature', 'in_force', '2024-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_91', ARRAY['sdg14', 'regulations', 'mandatory', 'usa', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c1cd6176-6123-51ea-b987-249f0c6d57e4', 'USA Washington Recycling Reform Law', 'Washington Recycling Reform Law', 'Washington’s SB 5284 introduces an Extended Producer Responsibility (EPR) framework requiring producers of packaging and paper products to finance and manage recycling systems. Effective in phases beginning 2027, the law mandates producers to join a stewardship organization that develops and submits a plan for statewide collection, sorting, and processing of recyclable materials. The law seeks to increase recycling rates, especially in underserved areas, and improve environmental outcomes by holding producers accountable from design to end-of-life. Local governments retain control over waste collection, ensuring continuity with existing systems. Exemptions apply to small producers and certain medical and agricultural packaging. The act establishes definitions, advisory councils, labeling requirements, performance goals, and enforcement mechanisms. It aims to improve convenience, accessibility, and the effectiveness of recycling while fostering public-private partnerships. SB 5284 positions Washington as a leader in circular economy policy, aligning with global efforts to shift waste burdens from consumers to manufacturers.', 'Washington’s SB 5284 introduces an Extended Producer Responsibility (EPR) framework requiring producers of packaging and paper products to finance and manage recycling systems. Effective in phases beginning 2027, the law mandates producers to join a stewardship organization that develops and submits a plan for statewide collection, sorting, and processing of recyclable materials. The law seeks to increase recycling rates, especially in underserved areas, and improve environmental outcomes by holding producers accountable from design to end-of-life. Local governments retain control over waste collection, ensuring continuity with existing systems. Exemptions apply to small producers and certain medical and agricultural packaging. The act establishes definitions, advisory councils, labeling requirements, performance goals, and enforcement mechanisms. It aims to improve convenience, accessibility, and the effectiveness of recycling while fostering public-private partnerships. SB 5284 positions Washington as a leader in circular economy policy, aligning with global efforts to shift waste burdens from consumers to manufacturers.', 'Washington’s SB 5284 introduces an Extended Producer Responsibility (EPR) framework requiring producers of packaging and paper products to finance and manage recycling systems. Effective in phases beginning 2027, the law mandates producers to join a stewardship organization that develops and submits a plan for statewide collection, sorting, and processing of recyclable materials. The law seeks to increase recycling rates, especially in underserved areas, and improve environmental outcomes by holding producers accountable from design to end-of-life. Local governments retain control over waste collection, ensuring continuity with existing systems. Exemptions apply to small producers and certain medical and agricultural packaging. The act establishes definitions, advisory councils, labeling requirements, performance goals, and enforcement mechanisms. It aims to improve convenience, accessibility, and the effectiveness of recycling while fostering public-private partnerships. SB 5284 positions Washington as a leader in circular economy policy, aligning with global efforts to shift waste burdens from consumers to manufacturers.', 'USA', 'nature', 'in_force', '2024-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_92', ARRAY['regulations', 'sdg17', 'mandatory', 'usa', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('da800af6-c475-5da6-8e37-f68aa5a12fa5', 'USA Washington Solid Waste Management Act', 'Washington Solid Waste Management Act', 'Washington’s FABRIC Act (SB 6039) introduces broad regulations aimed at increasing labor transparency and environmental sustainability within the fashion and apparel industry. It applies to manufacturers and retailers with over $100 million in annual revenue operating in Washington. Companies must map at least 50% of their supply chain, identifying risks related to labor abuses, child labor, wage theft, and environmental harms. They are required to disclose their due diligence and corrective actions through annual public reports. The law also mandates the development of science-based targets for greenhouse gas reductions and ethical sourcing practices. Enforcement includes civil penalties and oversight by the Department of Ecology. The FABRIC Act mirrors similar legislation introduced in New York and California, pushing corporate accountability for social and environmental harms across global supply chains. It reflects a growing legislative trend toward mandatory supply chain transparency and responsible business conduct in the fashion sector.', 'Washington’s FABRIC Act (SB 6039) introduces broad regulations aimed at increasing labor transparency and environmental sustainability within the fashion and apparel industry. It applies to manufacturers and retailers with over $100 million in annual revenue operating in Washington. Companies must map at least 50% of their supply chain, identifying risks related to labor abuses, child labor, wage theft, and environmental harms. They are required to disclose their due diligence and corrective actions through annual public reports. The law also mandates the development of science-based targets for greenhouse gas reductions and ethical sourcing practices. Enforcement includes civil penalties and oversight by the Department of Ecology. The FABRIC Act mirrors similar legislation introduced in New York and California, pushing corporate accountability for social and environmental harms across global supply chains. It reflects a growing legislative trend toward mandatory supply chain transparency and responsible business conduct in the fashion sector.', 'Washington’s FABRIC Act (SB 6039) introduces broad regulations aimed at increasing labor transparency and environmental sustainability within the fashion and apparel industry. It applies to manufacturers and retailers with over $100 million in annual revenue operating in Washington. Companies must map at least 50% of their supply chain, identifying risks related to labor abuses, child labor, wage theft, and environmental harms. They are required to disclose their due diligence and corrective actions through annual public reports. The law also mandates the development of science-based targets for greenhouse gas reductions and ethical sourcing practices. Enforcement includes civil penalties and oversight by the Department of Ecology. The FABRIC Act mirrors similar legislation introduced in New York and California, pushing corporate accountability for social and environmental harms across global supply chains. It reflects a growing legislative trend toward mandatory supply chain transparency and responsible business conduct in the fashion sector.', 'USA', 'climate', 'in_force', '2024-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_93', ARRAY['sdg13', 'regulations', 'mandatory', 'usa', 'sdg16', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c81a381e-ab2c-5953-8b8e-36a561372302', 'California AI Transparency Act', 'California AI Transparency Act', 'SB 942 mandates that developers of generative AI models in California provide transparent documentation on their training data, risk mitigation, and intended uses. The act applies to models released after 2026 with significant capabilities or societal risks. Developers must disclose summaries of the datasets, address safety concerns like bias or misinformation, and make reasonable efforts to prevent misuse. Enforcement lies with the Attorney General, and noncompliance can result in civil penalties. The act aims to ensure that as generative AI becomes more powerful and integrated into society, developers remain accountable and transparent about how their tools are trained and used. It also promotes ethical development by requiring disclosure of safeguards and potential risks. This act positions California as a leader in AI governance, balancing innovation with responsible practices in a rapidly evolving technological landscape.', 'SB 942 mandates that developers of generative AI models in California provide transparent documentation on their training data, risk mitigation, and intended uses. The act applies to models released after 2026 with significant capabilities or societal risks. Developers must disclose summaries of the datasets, address safety concerns like bias or misinformation, and make reasonable efforts to prevent misuse. Enforcement lies with the Attorney General, and noncompliance can result in civil penalties. The act aims to ensure that as generative AI becomes more powerful and integrated into society, developers remain accountable and transparent about how their tools are trained and used. It also promotes ethical development by requiring disclosure of safeguards and potential risks. This act positions California as a leader in AI governance, balancing innovation with responsible practices in a rapidly evolving technological landscape.', 'SB 942 mandates that developers of generative AI models in California provide transparent documentation on their training data, risk mitigation, and intended uses. The act applies to models released after 2026 with significant capabilities or societal risks. Developers must disclose summaries of the datasets, address safety concerns like bias or misinformation, and make reasonable efforts to prevent misuse. Enforcement lies with the Attorney General, and noncompliance can result in civil penalties. The act aims to ensure that as generative AI becomes more powerful and integrated into society, developers remain accountable and transparent about how their tools are trained and used. It also promotes ethical development by requiring disclosure of safeguards and potential risks. This act positions California as a leader in AI governance, balancing innovation with responsible practices in a rapidly evolving technological landscape.', 'USA', 'nature', 'in_force', '2024-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_94', ARRAY['sdg4', 'regulations', 'sdg9', 'mandatory', 'usa', 'sdg16', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('be72904c-ec07-5967-a860-a7b88fbf854e', 'California Senate Bill 261 (SB 261) – Climate-Related', 'California Senate Bill 261 (SB 261) – Climate-Related Financial Risk Disclosure', 'Senate Bill 261 (SB 261), enacted in October 2023, requires large businesses operating in California to disclose climate-related financial risks and the measures they are taking to mitigate those risks. The bill builds on California’s existing climate reporting laws and aligns with international climate disclosure frameworks such as the Task Force on Climate-related Financial Disclosures (TCFD).

Key provisions include:

Scope & Applicability:
Applies to corporations, partnerships, LLCs, and other business entities with total annual revenues exceeding $500 million that operate in California.
Excludes insurance companies, which are subject to separate reporting requirements.
Climate-Related Financial Risk Reports:
Covered entities must prepare and publish a climate-related financial risk report biennially, starting January 1, 2026.
Reports must include:
Identification of climate-related financial risks using TCFD guidelines.
Measures taken to mitigate and adapt to those risks.
Reports must be made publicly available on the company’s website.
Regulatory Oversight & Penalties:
The California Air Resources Board (CARB) is responsible for enforcement.
CARB will contract a climate reporting organization to review reports and assess sector-wide risks.
Companies failing to comply or publishing inadequate reports face administrative penalties up to $50,000 per reporting year.
Climate Risk Analysis & Public Reporting:
A biennial public report will analyze:
Sector-wide climate risks affecting California.
Gaps in corporate climate risk disclosures.
Fees & Funding:
Covered entities must pay an annual fee to fund CARB’s administration of the program.
Fees will be deposited into the Climate-Related Financial Risk Disclosure Fund, a continuously appropriated state fund.
SB 261 strengthens corporate accountability, transparency, and financial resilience in the face of climate change, positioning California as a leader in climate risk disclosure policy.', 'Senate Bill 261 (SB 261), enacted in October 2023, requires large businesses operating in California to disclose climate-related financial risks and the measures they are taking to mitigate those risks. The bill builds on California’s existing climate reporting laws and aligns with international climate disclosure frameworks such as the Task Force on Climate-related Financial Disclosures (TCFD).

