INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('be8ebaec-2564-545e-a12a-798a0c1a6fdd', 'USA SB-253 Climate Corporate Data Accountability Act', 'SB-253 Climate Corporate Data Accountability Act', 'Senate Bill 253, approved by the Governor of California on October 7, 2023, imposes new GHG emissions reporting rules for large corporations in California. Entities with revenues over $1 billion must disclose Scope 1 and Scope 2 emissions by 2026, and Scope 3 emissions by 2027. The California Air Resources Board (CARB) will finalize reporting regulations by January 1, 2025, and enforce compliance through third-party audits.

The bill aligns disclosures with the Greenhouse Gas Protocol and requires the state to provide a public digital platform for emissions data. Updates to requirements will follow periodic reviews of trends and standards. Reporting fees will fund administrative costs via the Climate Accountability and Emissions Disclosure Fund.', 'Senate Bill 253, approved by the Governor of California on October 7, 2023, imposes new GHG emissions reporting rules for large corporations in California. Entities with revenues over $1 billion must disclose Scope 1 and Scope 2 emissions by 2026, and Scope 3 emissions by 2027. The California Air Resources Board (CARB) will finalize reporting regulations by January 1, 2025, and enforce compliance through third-party audits.

The bill aligns disclosures with the Greenhouse Gas Protocol and requires the state to provide a public digital platform for emissions data. Updates to requirements will follow periodic reviews of trends and standards. Reporting fees will fund administrative costs via the Climate Accountability and Emissions Disclosure Fund.', 'Senate Bill 253, approved by the Governor of California on October 7, 2023, imposes new GHG emissions reporting rules for large corporations in California. Entities with revenues over $1 billion must disclose Scope 1 and Scope 2 emissions by 2026, and Scope 3 emissions by 2027. The California Air Resources Board (CARB) will finalize reporting regulations by January 1, 2025, and enforce compliance through third-party audits.

The bill aligns disclosures with the Greenhouse Gas Protocol and requires the state to provide a public digital platform for emissions data. Updates to requirements will follow periodic reviews of trends and standards. Reporting fees will fund administrative costs via the Climate Accountability and Emissions Disclosure Fund.', 'USA', 'climate', 'in_force', '2023-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_86', ARRAY['regulations', 'mandatory', 'usa', 'sdg12', 'disclosure', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('85085966-2755-5b9c-acaa-6ec8d949b14b', 'USA SB 261: Greenhouse Gases – Climate-Related Financial Risk', 'SB 261: Greenhouse Gases – Climate-Related Financial Risk', 'SB 261 requires large business entities operating in California to prepare and publicly disclose climate-related financial risk reports by January 1, 2026, and biennially thereafter. The reports must assess climate-related risks and the measures adopted to mitigate and adapt to these risks, using frameworks such as the Task Force on Climate-Related Financial Disclosures (TCFD). A state-appointed climate reporting organization will review these disclosures, analyze systemic climate risks, and publish findings. Noncompliance may result in administrative penalties up to $50,000 per reporting year. Entities are also required to pay fees to fund administrative implementation, creating a dedicated Climate-Related Financial Risk Disclosure Fund.', 'SB 261 requires large business entities operating in California to prepare and publicly disclose climate-related financial risk reports by January 1, 2026, and biennially thereafter. The reports must assess climate-related risks and the measures adopted to mitigate and adapt to these risks, using frameworks such as the Task Force on Climate-Related Financial Disclosures (TCFD). A state-appointed climate reporting organization will review these disclosures, analyze systemic climate risks, and publish findings. Noncompliance may result in administrative penalties up to $50,000 per reporting year. Entities are also required to pay fees to fund administrative implementation, creating a dedicated Climate-Related Financial Risk Disclosure Fund.', 'SB 261 requires large business entities operating in California to prepare and publicly disclose climate-related financial risk reports by January 1, 2026, and biennially thereafter. The reports must assess climate-related risks and the measures adopted to mitigate and adapt to these risks, using frameworks such as the Task Force on Climate-Related Financial Disclosures (TCFD). A state-appointed climate reporting organization will review these disclosures, analyze systemic climate risks, and publish findings. Noncompliance may result in administrative penalties up to $50,000 per reporting year. Entities are also required to pay fees to fund administrative implementation, creating a dedicated Climate-Related Financial Risk Disclosure Fund.', 'USA', 'climate', 'in_force', '2023-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_87', ARRAY['sdg13', 'sdg7', 'mandatory', 'usa', 'mandatory_regulations', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dca84b65-a6fb-578e-b158-9486e5b11ea2', 'USA AB-1305 Voluntary Carbon Market Disclosure Act', 'AB-1305 Voluntary Carbon Market Disclosure Act', 'AB 1305 establishes disclosure requirements for businesses marketing or selling voluntary carbon offsets within California. The bill mandates that entities provide detailed project information, including protocols used for estimating emissions reductions, project timelines, and validation details. Companies claiming carbon neutrality or net-zero emissions must disclose methodologies for verifying these claims, including third-party audits and progress tracking. Noncompliance results in civil penalties of up to $2,500 per day, capped at $500,000, enforceable by state or local legal authorities. Annual updates to disclosed information are required, ensuring transparency and accountability in carbon market claims and practices.', 'AB 1305 establishes disclosure requirements for businesses marketing or selling voluntary carbon offsets within California. The bill mandates that entities provide detailed project information, including protocols used for estimating emissions reductions, project timelines, and validation details. Companies claiming carbon neutrality or net-zero emissions must disclose methodologies for verifying these claims, including third-party audits and progress tracking. Noncompliance results in civil penalties of up to $2,500 per day, capped at $500,000, enforceable by state or local legal authorities. Annual updates to disclosed information are required, ensuring transparency and accountability in carbon market claims and practices.', 'AB 1305 establishes disclosure requirements for businesses marketing or selling voluntary carbon offsets within California. The bill mandates that entities provide detailed project information, including protocols used for estimating emissions reductions, project timelines, and validation details. Companies claiming carbon neutrality or net-zero emissions must disclose methodologies for verifying these claims, including third-party audits and progress tracking. Noncompliance results in civil penalties of up to $2,500 per day, capped at $500,000, enforceable by state or local legal authorities. Annual updates to disclosed information are required, ensuring transparency and accountability in carbon market claims and practices.', 'USA', 'governance', 'in_force', '2023-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_88', ARRAY['usa', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0333823c-e06c-5927-8ac5-734272b2e54a', 'USA H.R.5508 - Fostering Overseas Rule of Law', 'H.R.5508 - Fostering Overseas Rule of Law and Environmentally Sound Trade Act of 6 2023" ("FOREST" Act of 2023)', 'The FOREST Act of 2021 seeks to combat illegal deforestation by regulating the import of commodities produced on illegally deforested lands into the United States. It introduces stringent import declaration requirements, mandates supply chain traceability, and imposes penalties for non-compliance. The Act identifies key commodities at risk, including palm oil, soybeans, cocoa, cattle, rubber, and wood pulp. It also requires the U.S. Trade Representative to develop action plans for countries without adequate deforestation protections. With measures to enhance enforcement and international collaboration, the Act integrates anti-corruption, land tenure rights, and indigenous rights considerations, aligning U.S. trade with global environmental standards.', 'The FOREST Act of 2021 seeks to combat illegal deforestation by regulating the import of commodities produced on illegally deforested lands into the United States. It introduces stringent import declaration requirements, mandates supply chain traceability, and imposes penalties for non-compliance. The Act identifies key commodities at risk, including palm oil, soybeans, cocoa, cattle, rubber, and wood pulp. It also requires the U.S. Trade Representative to develop action plans for countries without adequate deforestation protections. With measures to enhance enforcement and international collaboration, the Act integrates anti-corruption, land tenure rights, and indigenous rights considerations, aligning U.S. trade with global environmental standards.', 'The FOREST Act of 2021 seeks to combat illegal deforestation by regulating the import of commodities produced on illegally deforested lands into the United States. It introduces stringent import declaration requirements, mandates supply chain traceability, and imposes penalties for non-compliance. The Act identifies key commodities at risk, including palm oil, soybeans, cocoa, cattle, rubber, and wood pulp. It also requires the U.S. Trade Representative to develop action plans for countries without adequate deforestation protections. With measures to enhance enforcement and international collaboration, the Act integrates anti-corruption, land tenure rights, and indigenous rights considerations, aligning U.S. trade with global environmental standards.', 'USA', 'nature', 'in_force', '2023-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_89', ARRAY['regulations', 'mandatory', 'usa', 'disclosure', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('79847ecf-5492-558b-98b0-19234e86fcad', 'USA Uighur Forced Labour Prevention Act', 'Uighur Forced Labour Prevention Act 2021', 'The "Uighur Forced Labor Prevention Act 2021" prohibits the importation of goods produced with forced labor in the Xinjiang Uighur Autonomous Region of China. The act requires companies to disclose their efforts to identify and eliminate forced labor in their supply chains, and provides for the imposition of sanctions against individuals and entities found to be involved in forced labor in the region. The act also establishes a rebuttable presumption that all goods produced in the Xinjiang region are made with forced labor, and requires U.S. Customs and Border Protection to seize any goods suspected of being produced with forced labor. The Uighur Forced Labor Prevention Act 2021 is intended to combat the use of forced labor in the production of goods, particularly in the textile and apparel industry, and to hold accountable those responsible for these practices. It is also intended to raise awareness of human rights abuses against the Uighur Muslim minority in China.', 'The "Uighur Forced Labor Prevention Act 2021" prohibits the importation of goods produced with forced labor in the Xinjiang Uighur Autonomous Region of China. The act requires companies to disclose their efforts to identify and eliminate forced labor in their supply chains, and provides for the imposition of sanctions against individuals and entities found to be involved in forced labor in the region. The act also establishes a rebuttable presumption that all goods produced in the Xinjiang region are made with forced labor, and requires U.S. Customs and Border Protection to seize any goods suspected of being produced with forced labor. The Uighur Forced Labor Prevention Act 2021 is intended to combat the use of forced labor in the production of goods, particularly in the textile and apparel industry, and to hold accountable those responsible for these practices. It is also intended to raise awareness of human rights abuses against the Uighur Muslim minority in China.', 'The "Uighur Forced Labor Prevention Act 2021" prohibits the importation of goods produced with forced labor in the Xinjiang Uighur Autonomous Region of China. The act requires companies to disclose their efforts to identify and eliminate forced labor in their supply chains, and provides for the imposition of sanctions against individuals and entities found to be involved in forced labor in the region. The act also establishes a rebuttable presumption that all goods produced in the Xinjiang region are made with forced labor, and requires U.S. Customs and Border Protection to seize any goods suspected of being produced with forced labor. The Uighur Forced Labor Prevention Act 2021 is intended to combat the use of forced labor in the production of goods, particularly in the textile and apparel industry, and to hold accountable those responsible for these practices. It is also intended to raise awareness of human rights abuses against the Uighur Muslim minority in China.', 'USA', 'climate', 'in_force', '2021-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_84', ARRAY['sdg8', 'regulations', 'mandatory', 'usa', 'sdg16', 'sdg12', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('baef4e01-07ad-5dc5-8a4a-1d7dec2f4973', 'USA ESG Disclosure Simplification Act of', 'ESG Disclosure Simplification Act of 2021', 'This act aims to reduce the reporting burden on companies while promoting more consistent and comparable ESG disclosures. It would require the Securities and Exchange Commission (SEC) to review and consolidate its ESG disclosure requirements and issue new regulations that reflect current market practices and investor needs. The act also requires the SEC to take into account the materiality of ESG information and the costs and benefits of reporting, and to ensure that any new regulations are aligned with international reporting frameworks. The ESG Disclosure Simplification Act of 2021 is intended to provide investors with the information they need to make informed investment decisions while reducing the reporting burden on companies and promoting greater consistency and comparability in ESG disclosures.', 'This act aims to reduce the reporting burden on companies while promoting more consistent and comparable ESG disclosures. It would require the Securities and Exchange Commission (SEC) to review and consolidate its ESG disclosure requirements and issue new regulations that reflect current market practices and investor needs. The act also requires the SEC to take into account the materiality of ESG information and the costs and benefits of reporting, and to ensure that any new regulations are aligned with international reporting frameworks. The ESG Disclosure Simplification Act of 2021 is intended to provide investors with the information they need to make informed investment decisions while reducing the reporting burden on companies and promoting greater consistency and comparability in ESG disclosures.', 'This act aims to reduce the reporting burden on companies while promoting more consistent and comparable ESG disclosures. It would require the Securities and Exchange Commission (SEC) to review and consolidate its ESG disclosure requirements and issue new regulations that reflect current market practices and investor needs. The act also requires the SEC to take into account the materiality of ESG information and the costs and benefits of reporting, and to ensure that any new regulations are aligned with international reporting frameworks. The ESG Disclosure Simplification Act of 2021 is intended to provide investors with the information they need to make informed investment decisions while reducing the reporting burden on companies and promoting greater consistency and comparability in ESG disclosures.', 'USA', 'climate', 'in_force', '2021-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_85', ARRAY['sdg13', 'regulations', 'mandatory', 'usa', 'sdg16', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b62bb54a-c1c1-557a-aa8f-316e66802455', 'USA H.R.1187 - Corporate Governance Improvement and Investor Protection', 'H.R.1187 - Corporate Governance Improvement and Investor Protection Act', 'This legislation aims to enhance corporate governance practices and improve investor protections by mandating additional disclosures from public companies. Key elements include:

Establishment of Environmental, Social, and Governance (ESG) disclosure standards to ensure uniformity and transparency for investors.
Creation of a Sustainable Finance Advisory Committee to guide the Securities and Exchange Commission (SEC) on ESG metrics.
Introduction of reporting obligations regarding corporate political spending, climate risk, executive pay ratios, and offshoring activities.
Encouragement of companies to adopt international standards for sustainability reporting and incorporate material climate-related financial risks in annual filings.
The bill emphasizes the economic and systemic risks posed by climate change and underscores the need for a smooth transition to a sustainable, low-emissions economy.', 'This legislation aims to enhance corporate governance practices and improve investor protections by mandating additional disclosures from public companies. Key elements include:

Establishment of Environmental, Social, and Governance (ESG) disclosure standards to ensure uniformity and transparency for investors.
Creation of a Sustainable Finance Advisory Committee to guide the Securities and Exchange Commission (SEC) on ESG metrics.
Introduction of reporting obligations regarding corporate political spending, climate risk, executive pay ratios, and offshoring activities.
Encouragement of companies to adopt international standards for sustainability reporting and incorporate material climate-related financial risks in annual filings.
The bill emphasizes the economic and systemic risks posed by climate change and underscores the need for a smooth transition to a sustainable, low-emissions economy.', 'This legislation aims to enhance corporate governance practices and improve investor protections by mandating additional disclosures from public companies. Key elements include:

Establishment of Environmental, Social, and Governance (ESG) disclosure standards to ensure uniformity and transparency for investors.
Creation of a Sustainable Finance Advisory Committee to guide the Securities and Exchange Commission (SEC) on ESG metrics.
Introduction of reporting obligations regarding corporate political spending, climate risk, executive pay ratios, and offshoring activities.
Encouragement of companies to adopt international standards for sustainability reporting and incorporate material climate-related financial risks in annual filings.
The bill emphasizes the economic and systemic risks posed by climate change and underscores the need for a smooth transition to a sustainable, low-emissions economy.', 'USA', 'climate', 'in_force', '2021-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_90', ARRAY['mandatory', 'usa', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('efa3d545-ffbf-5cd8-ac91-84fd663a5800', 'USA Stewardship Principles', 'The Stewardship Principles, 2020', 'Institutional investors should demonstrate how they evaluate corporate governance factors with respect to the companies in which they invest. They should disclose potential conflicts of interest that may arise in their proxy voting and engagement activities. Where appropriate, they should work together to encourage the adoption and implementation of the Corporate Governance and Stewardship principles.', 'Institutional investors should demonstrate how they evaluate corporate governance factors with respect to the companies in which they invest. They should disclose potential conflicts of interest that may arise in their proxy voting and engagement activities. Where appropriate, they should work together to encourage the adoption and implementation of the Corporate Governance and Stewardship principles.', 'Institutional investors should demonstrate how they evaluate corporate governance factors with respect to the companies in which they invest. They should disclose potential conflicts of interest that may arise in their proxy voting and engagement activities. Where appropriate, they should work together to encourage the adoption and implementation of the Corporate Governance and Stewardship principles.', 'USA', 'governance', 'in_force', '2020-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_18', ARRAY['guidance_frameworks', 'other sustainability policy', 'usa', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
