INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a3230c18-3383-5a68-ae0c-0815af162f1d', 'USA 17 CFR Parts 211, 231, and 241 [Release', '17 CFR Parts 211, 231, and 241 [Release Nos. 33-10751; 34-88094; FR-87] Commission Guidance on Management’s Discussion and Analysis of Financial Condition and Results of Operations', 'This document provides guidance on key performance indicators and metrics in Management’s Discussion and Analysis of Financial Condition and Results of Operations (“MD&A”).', 'This document provides guidance on key performance indicators and metrics in Management’s Discussion and Analysis of Financial Condition and Results of Operations (“MD&A”).', 'This document provides guidance on key performance indicators and metrics in Management’s Discussion and Analysis of Financial Condition and Results of Operations (“MD&A”).', 'USA', 'governance', 'in_force', '2020-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_83', ARRAY['usa', 'guidance_frameworks', 'mandatory', 'other sustainability policy']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('af44d87e-2886-53df-ba90-8f35b4032421', 'USA ESG Reporting Guide 2.0: A support resource for', 'ESG Reporting Guide 2.0: A support resource for companies, 2019', 'This  version of the ESG Reporting Guide is intended to meet several goals including elimiating and revise uncommon or impractical metrics, incorporating new developments in the marketplace (such as TCFD, SDGs, GRI Standards, EU NFR Directive, and others), simplifying and standardizing guidance, labels, and calculations, improving ESG engagement for small- and medium-sized business enterprises as well as attempting to cover all Nasdaq markets – including the U.S. equities market – in a single document.', 'This  version of the ESG Reporting Guide is intended to meet several goals including elimiating and revise uncommon or impractical metrics, incorporating new developments in the marketplace (such as TCFD, SDGs, GRI Standards, EU NFR Directive, and others), simplifying and standardizing guidance, labels, and calculations, improving ESG engagement for small- and medium-sized business enterprises as well as attempting to cover all Nasdaq markets – including the U.S. equities market – in a single document.', 'This  version of the ESG Reporting Guide is intended to meet several goals including elimiating and revise uncommon or impractical metrics, incorporating new developments in the marketplace (such as TCFD, SDGs, GRI Standards, EU NFR Directive, and others), simplifying and standardizing guidance, labels, and calculations, improving ESG engagement for small- and medium-sized business enterprises as well as attempting to cover all Nasdaq markets – including the U.S. equities market – in a single document.', 'USA', 'climate', 'in_force', '2019-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_23', ARRAY['sdg13', 'other sustainability policy', 'mandatory', 'usa', 'sdg16', 'mandatory_regulations', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fa77716b-7f88-5ef7-8470-e56e89215a48', 'USA Act to amend Title 6 of the Delaware', 'An Act to amend Title 6 of the Delaware Code Relating to the Certification of Adoption of Sustainability and Transparency Standards by Delaware Entities', 'This document is concerned with an act to amend Title 6 of the Delaware Code Relating to the Certification of Adoption of Sustainability and Transparency Standards by Delaware Entities.', 'This document is concerned with an act to amend Title 6 of the Delaware Code Relating to the Certification of Adoption of Sustainability and Transparency Standards by Delaware Entities.', 'This document is concerned with an act to amend Title 6 of the Delaware Code Relating to the Certification of Adoption of Sustainability and Transparency Standards by Delaware Entities.', 'USA', 'governance', 'in_force', '2018-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_17', ARRAY['regulations', 'mandatory', 'usa', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3be34392-49c0-5fef-a8e3-b7b60e51b961', 'USA Title 33 - Navigation and Navigable Waters', 'Title 33 - Navigation and Navigable Waters', 'The U.S. Code of Federal Regulations is divided into 50 titles that encompass administrative law for agencies of the federal government of United States. CFR 33 details regulations pertaining to navigation and navigable waters. The title is made up of three volumes, written by different agencies, including: the U.S. Coast Guard, the Army Corp of Engineers and the Saint Lawrence Seaway Development Corporation.', 'The U.S. Code of Federal Regulations is divided into 50 titles that encompass administrative law for agencies of the federal government of United States. CFR 33 details regulations pertaining to navigation and navigable waters. The title is made up of three volumes, written by different agencies, including: the U.S. Coast Guard, the Army Corp of Engineers and the Saint Lawrence Seaway Development Corporation.', 'The U.S. Code of Federal Regulations is divided into 50 titles that encompass administrative law for agencies of the federal government of United States. CFR 33 details regulations pertaining to navigation and navigable waters. The title is made up of three volumes, written by different agencies, including: the U.S. Coast Guard, the Army Corp of Engineers and the Saint Lawrence Seaway Development Corporation.', 'USA', 'nature', 'in_force', '2018-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_20', ARRAY['sdg14', 'other sustainability policy', 'regulations', 'mandatory', 'sdg6', 'usa']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('da45d7b8-ac80-5306-8371-82a1cb964e2f', 'USA Commonsense Principles 2.0', 'Commonsense Principles 2.0, 2018', 'This document is the revised version of the commonsense principles of corporate governance which are the intended to provide a basic framework for sound, long-term-oriented governance.', 'This document is the revised version of the commonsense principles of corporate governance which are the intended to provide a basic framework for sound, long-term-oriented governance.', 'This document is the revised version of the commonsense principles of corporate governance which are the intended to provide a basic framework for sound, long-term-oriented governance.', 'USA', 'governance', 'in_force', '2018-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_22', ARRAY['guidance_frameworks', 'usa', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8af85c1b-11b7-5a36-99ae-72a0052141bf', 'USA Field Assistance Bulletin', 'Field Assistance Bulletin NO. 2018-01', 'This Field Assistance Bulletin provides guidance to the Employee Benefits Security Administration’s national and regional offices to assist in addressing questions they may receive from plan fiduciaries and other interested stakeholders about Interpretive Bulletin 2016-011 (relating to the exercise of shareholder rights and written statements of investment policy), and Interpretive Bulletin 2015-012 (relating to “economically targeted investments” (ETIs)).', 'This Field Assistance Bulletin provides guidance to the Employee Benefits Security Administration’s national and regional offices to assist in addressing questions they may receive from plan fiduciaries and other interested stakeholders about Interpretive Bulletin 2016-011 (relating to the exercise of shareholder rights and written statements of investment policy), and Interpretive Bulletin 2015-012 (relating to “economically targeted investments” (ETIs)).', 'This Field Assistance Bulletin provides guidance to the Employee Benefits Security Administration’s national and regional offices to assist in addressing questions they may receive from plan fiduciaries and other interested stakeholders about Interpretive Bulletin 2016-011 (relating to the exercise of shareholder rights and written statements of investment policy), and Interpretive Bulletin 2015-012 (relating to “economically targeted investments” (ETIs)).', 'USA', 'governance', 'in_force', '2018-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_50', ARRAY['usa', 'guidance_frameworks', 'mandatory', 'other sustainability policy']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e9677dae-9c1e-59bb-a713-1cab7416fee3', 'USA Improving Critical Infrastructure Cybersecurity', 'Framework for Improving Critical Infrastructure Cybersecurity, 2018', 'This version of the Cybersecurity Framework refines, clarifies, and enhances Version 1.0, which was issued in February 2014. It incorporates comments received on the two drafts of Version 1.1. Additionally, it is intended to be implemented by first-time and current Framework users.', 'This version of the Cybersecurity Framework refines, clarifies, and enhances Version 1.0, which was issued in February 2014. It incorporates comments received on the two drafts of Version 1.1. Additionally, it is intended to be implemented by first-time and current Framework users.', 'This version of the Cybersecurity Framework refines, clarifies, and enhances Version 1.0, which was issued in February 2014. It incorporates comments received on the two drafts of Version 1.1. Additionally, it is intended to be implemented by first-time and current Framework users.', 'USA', 'governance', 'in_force', '2018-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_82', ARRAY['other sustainability policy', 'voluntary', 'usa', 'sdg9', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
