INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a7c727bc-5766-5097-8968-5bafc278c623', 'USA Commonsense Principles of Corporate Governance', 'Commonsense Principles of Corporate Governance, 2016', 'This document contains a series of corporate governance principles for public companies, their board of directors and their shareholders. These principles are intended to provide a basic framework for sound, long-term- oriented governance.', 'This document contains a series of corporate governance principles for public companies, their board of directors and their shareholders. These principles are intended to provide a basic framework for sound, long-term- oriented governance.', 'This document contains a series of corporate governance principles for public companies, their board of directors and their shareholders. These principles are intended to provide a basic framework for sound, long-term- oriented governance.', 'USA', 'governance', 'in_force', '2016-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_29', ARRAY['guidance_frameworks', 'usa', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a2415d44-efc7-5267-9562-51d23bdab477', 'USA Principles of Corporate Governance', 'Principles of Corporate Governance, 2016', 'This is the 2016 version of the Business Roundtable principles which are intended to assist corporate management and boards of directors in their individual efforts to implement best practices of corporate governance, and also to serve as guideposts.', 'This is the 2016 version of the Business Roundtable principles which are intended to assist corporate management and boards of directors in their individual efforts to implement best practices of corporate governance, and also to serve as guideposts.', 'This is the 2016 version of the Business Roundtable principles which are intended to assist corporate management and boards of directors in their individual efforts to implement best practices of corporate governance, and also to serve as guideposts.', 'USA', 'governance', 'in_force', '2016-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_38', ARRAY['guidance_frameworks', 'other sustainability policy', 'usa', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('691ec3ac-12f5-5671-94b8-b24d44ef6106', 'USA Interpretive Bulletin Relating to the Exercise of Shareholder', 'Interpretive Bulletin Relating to the Exercise of Shareholder Rights and Written Statements of Investment Policy, including Proxy Voting Policies or Guidelines, 2016', 'This document sets forth supplemental views of the Department of Labor (Department) concerning the legal standards imposed by sections 402, 403 and 404 of Part 4 of Title I of the Employee Retirement Income Security Act of 1974 (ERISA) with respect to voting of proxies on securities held in employee benefit plan investment portfolios, the maintenance of and compliance with statements of investment policy, including proxy voting policy, and the exercise of other legal rights of a shareholder. In this document, the Department withdraws Interpretive Bulletin 2008–2 and replaces it with Interpretive Bulletin 2016–1, which reinstates the language of Interpretive Bulletin 94–2 with certain modifications.', 'This document sets forth supplemental views of the Department of Labor (Department) concerning the legal standards imposed by sections 402, 403 and 404 of Part 4 of Title I of the Employee Retirement Income Security Act of 1974 (ERISA) with respect to voting of proxies on securities held in employee benefit plan investment portfolios, the maintenance of and compliance with statements of investment policy, including proxy voting policy, and the exercise of other legal rights of a shareholder. In this document, the Department withdraws Interpretive Bulletin 2008–2 and replaces it with Interpretive Bulletin 2016–1, which reinstates the language of Interpretive Bulletin 94–2 with certain modifications.', 'This document sets forth supplemental views of the Department of Labor (Department) concerning the legal standards imposed by sections 402, 403 and 404 of Part 4 of Title I of the Employee Retirement Income Security Act of 1974 (ERISA) with respect to voting of proxies on securities held in employee benefit plan investment portfolios, the maintenance of and compliance with statements of investment policy, including proxy voting policy, and the exercise of other legal rights of a shareholder. In this document, the Department withdraws Interpretive Bulletin 2008–2 and replaces it with Interpretive Bulletin 2016–1, which reinstates the language of Interpretive Bulletin 94–2 with certain modifications.', 'USA', 'climate', 'in_force', '2016-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_51', ARRAY['usa', 'guidance_frameworks', 'voluntary', 'other sustainability policy']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7a63643a-fedf-5ce5-83e1-d29675211e3e', 'USA ECMPS Reporting Instructions Emissions', 'ECMPS Reporting Instructions Emissions, 2016', 'The purpose of the reporting instructions is to provide the necessary information for owners and operators to meet the reporting requirements for sources affected by: The Acid Rain Program (ARP); The Cross-State Air Pollution Rule (CSAPR); The Mercury and Air Toxic Standards Rule (MATS); and other programs required to report data using these XML schemas.', 'The purpose of the reporting instructions is to provide the necessary information for owners and operators to meet the reporting requirements for sources affected by: The Acid Rain Program (ARP); The Cross-State Air Pollution Rule (CSAPR); The Mercury and Air Toxic Standards Rule (MATS); and other programs required to report data using these XML schemas.', 'The purpose of the reporting instructions is to provide the necessary information for owners and operators to meet the reporting requirements for sources affected by: The Acid Rain Program (ARP); The Cross-State Air Pollution Rule (CSAPR); The Mercury and Air Toxic Standards Rule (MATS); and other programs required to report data using these XML schemas.', 'USA', 'climate', 'in_force', '2016-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_77', ARRAY['sdg13', 'mandatory', 'usa', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('11dda036-5e4b-5b3b-ae91-efcf68d10f65', 'USA ECMPS Reporting Instructions Monitoring Plan', 'ECMPS Reporting Instructions Monitoring Plan, 2016', 'This Monitoring Plan describes how a monitoring configuration monitors its emissions.', 'This Monitoring Plan describes how a monitoring configuration monitors its emissions.', 'This Monitoring Plan describes how a monitoring configuration monitors its emissions.', 'USA', 'climate', 'in_force', '2016-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_78', ARRAY['sdg13', 'mandatory', 'usa', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0f3cdb9a-ad99-5ae7-ad0b-837034450c22', 'USA Greenhouse Gas Inventory Guidance Direct Emissions from Mobile', 'Greenhouse Gas Inventory Guidance Direct Emissions from Mobile Combustion Sources, 2016', 'This document presents the guidance for calculating scope 1 direct GHG emissions resulting from the operation of owned or leased mobile sources that are within an organization’s inventory boundary. This guidance applies to all sectors whose operations include owned or leased mobile sources.', 'This document presents the guidance for calculating scope 1 direct GHG emissions resulting from the operation of owned or leased mobile sources that are within an organization’s inventory boundary. This guidance applies to all sectors whose operations include owned or leased mobile sources.', 'This document presents the guidance for calculating scope 1 direct GHG emissions resulting from the operation of owned or leased mobile sources that are within an organization’s inventory boundary. This guidance applies to all sectors whose operations include owned or leased mobile sources.', 'USA', 'climate', 'in_force', '2016-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_79', ARRAY['guidance_frameworks', 'sdg13', 'other sustainability policy', 'mandatory', 'usa']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('656235c7-7549-544e-ab2d-95bb97e7c48f', 'USA Greenhouse Gas Inventory Guidance Direct Emissions from Stationary', 'Greenhouse Gas Inventory Guidance Direct Emissions from Stationary Combustion Sources, 2016', 'This document presents guidance for calculating the scope of direct GHG emissions resulting from stationary combustion of fuels at owned/operated sources. This guidance applies to all organizations whose operations involve stationary combustion of fuel.', 'This document presents guidance for calculating the scope of direct GHG emissions resulting from stationary combustion of fuels at owned/operated sources. This guidance applies to all organizations whose operations involve stationary combustion of fuel.', 'This document presents guidance for calculating the scope of direct GHG emissions resulting from stationary combustion of fuels at owned/operated sources. This guidance applies to all organizations whose operations involve stationary combustion of fuel.', 'USA', 'climate', 'in_force', '2016-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_80', ARRAY['guidance_frameworks', 'sdg13', 'other sustainability policy', 'mandatory', 'usa']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8f69eca2-a898-58f7-8eba-c2bffa1e34d7', 'Federal Aquisition Regulation; Ending Trafficking in Persons', 'Federal Aquisition Regulation; Ending Trafficking in Persons', 'DoD, GSA, and NASA have issued a final rule amending the Federal Acquisition Regulation (FAR) to strengthen protections against trafficking in persons in Federal contracts. These changes are intended to implement Executive Order (E.O.) 13627, entitled ‘‘Strengthening Protections Against Trafficking in Persons in Federal Contracts,’’ and title XVII of the National Defense Authorization Act for Fiscal Year 2013.', 'DoD, GSA, and NASA have issued a final rule amending the Federal Acquisition Regulation (FAR) to strengthen protections against trafficking in persons in Federal contracts. These changes are intended to implement Executive Order (E.O.) 13627, entitled ‘‘Strengthening Protections Against Trafficking in Persons in Federal Contracts,’’ and title XVII of the National Defense Authorization Act for Fiscal Year 2013.', 'DoD, GSA, and NASA have issued a final rule amending the Federal Acquisition Regulation (FAR) to strengthen protections against trafficking in persons in Federal contracts. These changes are intended to implement Executive Order (E.O.) 13627, entitled ‘‘Strengthening Protections Against Trafficking in Persons in Federal Contracts,’’ and title XVII of the National Defense Authorization Act for Fiscal Year 2013.', 'USA', 'governance', 'in_force', '2015-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_16', ARRAY['usa', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('70bdc73a-7061-51db-b785-47f925b07ec1', 'USA Interpretive Bulletin Relating to the Fiduciary Standard Under', 'Interpretive Bulletin Relating to the Fiduciary Standard Under ERISA in Considering Economically Targeted Investments', 'This document sets forth supplemental views of the Department of Labor (Department) concerning the legal standard imposed by sections 403 and 404 of Part 4 of Title I of the Employee Retirement Income Security Act of 1974 (ERISA) with respect to a plan fiduciary’s decision to invest plan assets in ‘‘economically targeted investments’’(ETIs).', 'This document sets forth supplemental views of the Department of Labor (Department) concerning the legal standard imposed by sections 403 and 404 of Part 4 of Title I of the Employee Retirement Income Security Act of 1974 (ERISA) with respect to a plan fiduciary’s decision to invest plan assets in ‘‘economically targeted investments’’(ETIs).', 'This document sets forth supplemental views of the Department of Labor (Department) concerning the legal standard imposed by sections 403 and 404 of Part 4 of Title I of the Employee Retirement Income Security Act of 1974 (ERISA) with respect to a plan fiduciary’s decision to invest plan assets in ‘‘economically targeted investments’’(ETIs).', 'USA', 'social', 'in_force', '2015-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_19', ARRAY['sdg8', 'other sustainability policy', 'voluntary', 'usa', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4d629865-e0bb-572f-8bcd-b590680ee1ed', 'USA Senate Bill Chapter 605 An act to amend', 'Senate Bill No. 185 Chapter 605 An act to amend Section 16642 of, and to add Section 7513.75 to, the Government Code, relating to public retirement systems', 'This document is concerned with an act to amend Section 16642 of, and to add Section 7513.75 to, the Government Code, relating to public retirement systems.', 'This document is concerned with an act to amend Section 16642 of, and to add Section 7513.75 to, the Government Code, relating to public retirement systems.', 'This document is concerned with an act to amend Section 16642 of, and to add Section 7513.75 to, the Government Code, relating to public retirement systems.', 'USA', 'governance', 'in_force', '2015-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_21', ARRAY['usa', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3cfd570f-7f32-5505-b091-3ff3e8f47a4f', 'California Transparency in Supply Chains Act', 'The California Transparency in Supply Chains Act, 2015', 'This Resource Guide is intended to help covered companies by offering recommendations about model disclosures and best practices for developing such disclosures. In each disclosure category, the Guide discusses how a company can provide disclosures that comply with the law, as well as enhance consumers’ understanding of its anti-trafficking and anti-slavery efforts.', 'This Resource Guide is intended to help covered companies by offering recommendations about model disclosures and best practices for developing such disclosures. In each disclosure category, the Guide discusses how a company can provide disclosures that comply with the law, as well as enhance consumers’ understanding of its anti-trafficking and anti-slavery efforts.', 'This Resource Guide is intended to help covered companies by offering recommendations about model disclosures and best practices for developing such disclosures. In each disclosure category, the Guide discusses how a company can provide disclosures that comply with the law, as well as enhance consumers’ understanding of its anti-trafficking and anti-slavery efforts.', 'USA', 'circularity', 'in_force', '2015-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_73', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'usa', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fd386416-1eb0-5959-87ac-b605879b7be3', 'USA M&V Guidelines: Measurement and Verification for Performance-Based Contracts', 'M&V Guidelines: Measurement and Verification for Performance-Based Contracts Version 4.0', 'This document contains procedures and guidelines for quantifying the savings resulting from energy efficient equipment, water conservation, improved operation and maintenance, renewable energy, and cogeneration projects installed under performance-based contracts. It is intended for energy managers, procurement officers, and contractors involved in implementing such measures. Additionally, the document has two primary purposes including serving as a reference document for specifying M&V methods and procedures and as a resource for those developing project-specific M&V plans.', 'This document contains procedures and guidelines for quantifying the savings resulting from energy efficient equipment, water conservation, improved operation and maintenance, renewable energy, and cogeneration projects installed under performance-based contracts. It is intended for energy managers, procurement officers, and contractors involved in implementing such measures. Additionally, the document has two primary purposes including serving as a reference document for specifying M&V methods and procedures and as a resource for those developing project-specific M&V plans.', 'This document contains procedures and guidelines for quantifying the savings resulting from energy efficient equipment, water conservation, improved operation and maintenance, renewable energy, and cogeneration projects installed under performance-based contracts. It is intended for energy managers, procurement officers, and contractors involved in implementing such measures. Additionally, the document has two primary purposes including serving as a reference document for specifying M&V methods and procedures and as a resource for those developing project-specific M&V plans.', 'USA', 'climate', 'in_force', '2015-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_74', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'sdg6', 'usa', 'sdg12', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
